        "cislo": 111,
        "otazka": "Ak vodič počas jazdy zistí, že vozidlo nespĺňa ustanovené podmienky",
        "moznosti": [
            {
                "id": "a",
                "text": "môže pokračovať podľa potreby do miesta, kde je možné chybu odstrániť, počas jazdy nemusí urobiť žiadne opatrenia"
            },
            {
                "id": "b",
                "text": "môže pokračovať ďalej v jazde primeranou rýchlosťou avšak musí urobiť také opatrenia, aby sa počas jazdy neohrozila bezpečnosť ani plynulosť cestnej premávky a aby sa nepoškodila cesta"
            },
            {
                "id": "c",
                "text": "je povinný chybu odstrániť na najbližšom mieste čerpania denného odpočinku, pričom do tohto miesta smie pokračovať primeranou rýchlosťou avšak musí urobiť také opatrenia, aby sa počas jazdy neohrozila bezpečnosť ani plynulosť cestnej premávky a aby sa nepoškodila cesta"
            },
            {
                "id": "d",
                "text": "je povinný chybu odstrániť na mieste. Ak to nemôže urobiť, smie v jazde pokračovať primeranou rýchlosťou len do najbližšieho miesta, kde možno chybu odstrániť. Pritom musí urobiť také opatrenia, aby sa počas jazdy na takéto miesto neohrozila bezpečnosť ani plynulosť cestnej premávky a aby sa nepoškodila cesta"
            }
        ],
