                "text": "vodič je povinný upozorniť cestujúceho na jeho správanie, v prípade neuposlúchnutia výzvy cestujúceho je vodič povinný posadiť cestujúceho na sedadlo vedľa vodiča a zabezpečiť jeho vhodné správanie,"
