                "text": "vodič môže jazdiť ešte 28 minút, následne musí čerpať odpočinok 3 h a 50 minút, v týždni už mal 3 krát 9 hodinový denný odpočinok, nasledujúci denný odpočinok musí byť minimálne 11 hodín"
