        "moznosti": [
            {
                "id": "a",
                "text": "áno, pri tvorbe harmonogramu prepravy je potrebné zapracovať požiadavky sociálnej legislatívy (Nariadenie (ES) č. 561/2006 a Dohoda AETR)"
            },
            {
                "id": "b",
                "text": "áno, pri tvorbe harmonogramu prepravy je potrebné zapracovať požiadavky sociálnej legislatívy, ale iba pri vnútroštátnej doprave"
            },
            {
                "id": "c",
                "text": "áno, pri tvorbe harmonogramu prepravy je potrebné zapracovať požiadavky sociálnej legislatívy, ale iba pri medzinárodnej doprave"
            },
            {
                "id": "d",
                "text": "nie, pri tvorbe harmonogramu prepravy nie je potrebné zapracovávať požiadavky sociálnej legislatívy; za bezpečnostné prestávky a denný čas odpočinku je zodpovedný výlučne vodič"
            }
        ],
        "spravne": [
            "a"
        ],
        "obrazok": null
